 const[products,setProducts]=useState([]),[category,setCategory]=useState('all'),[search,setSearch]=useState(()=>{try{return sessionStorage.getItem('shambavet_market_search')||''}catch{return ''}}),[detailProduct,setDetailProduct]=useState(null),[userLocation,setUserLocation]=useState(null),[locating,setLocating]=useState(false),[locationMessage,setLocationMessage]=useState('');
