 const shops=Object.values(normalizedProducts.filter(p=>p.shop&&p.shopLat!=null&&p.shopLng!=null).reduce((acc,p)=>{const key=String(p.shop).trim().toLowerCase()+'|'+Number(p.shopLat).toFixed(5)+'|'+Number(p.shopLng).toFixed(5);if(!acc[key])acc[key]={shop:p.shop,address:p.shopAddress||'',phone:p.phone||'',lat:Number(p.shopLat),lng:Number(p.shopLng),categories:new Set(),products:0};acc[key].categories.add(p.marketCategory);acc[key].products++;if(!acc[key].phone&&p.phone)acc[key].phone=p.phone;return acc;},{})).map(x=>({...x,categories:[...x.categories]}));
